var ConversationMemoryEngine = class {
  /**
   * Compresses recent turns of a conversation history
   */
  static compressAndSummarizeHistory(messages, options) {
    if (!Array.isArray(messages)) return [];
    const maxRecentTurns = options?.maxRecentTurns || 4;
    const maxCharsPerMsg = options?.maxCharsPerMsg || 220;
    const recent = messages.slice(-maxRecentTurns * 2);
    return recent.map((msg) => ({
      role: msg.role,
      content: msg.content.length > maxCharsPerMsg ? msg.content.substring(0, maxCharsPerMsg) + "..." : msg.content
    }));
  }
};

