      friendly: "\u062A\u0645\u0627\u06CC\u0644 \u0648 \u0627\u062D\u0633\u0627\u0633\u062A \u0631\u0648 \u062F\u0631\u06A9 \u0645\u06CC\u200C\u06A9\u0646\u0645\u060C \u0627\u0645\u0627 \u0645\u0646 \u0622\u062F\u0645\u06CC \u0647\u0633\u062A\u0645 \u06A9\u0647 \u0628\u0627\u06CC\u062F \u0627\u0648\u0644 \u0627\u0632 \u0646\u0638\u0631 \u0641\u06A9\u0631\u06CC \u0648 \u0635\u0645\u06CC\u0645\u06CC\u062A \u0642\u0644\u0628\u06CC \u06A9\u0627\u0645\u0644\u0627\u064B \u0628\u0647 \u0647\u0645 \u0646\u0632\u062F\u06CC\u06A9 \u0628\u0634\u06CC\u0645 \u062A\u0627 \u062D\u0633 \u062E\u0648\u0628\u06CC \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u0645.",
      charismatic: "\u0635\u0645\u06CC\u0645\u06CC\u062A \u0628\u0627 \u0645\u0646 \u06CC\u06A9 \u062C\u0627\u06CC\u0632\u0647 \u0627\u0633\u062A \u06A9\u0647 \u0641\u0642\u0637 \u0628\u0647 \u06CC\u06A9 \u0627\u0631\u062A\u0628\u0627\u0637 \u0639\u0645\u06CC\u0642\u060C \u0627\u0645\u0646 \u0648 \u067E\u0627\u06CC\u062F\u0627\u0631 \u062A\u0639\u0644\u0642 \u0645\u06CC\u200C\u06AF\u06CC\u0631\u0647\u060C \u0646\u0647 \u06CC\u06A9 \u062F\u0631\u062E\u0648\u0627\u0633\u062A \u0634\u062A\u0627\u0628\u200C\u0632\u062F\u0647. \u0628\u06CC\u0627 \u0627\u0648\u0644 \u0628\u0628\u06CC\u0646\u06CC\u0645 \u0639\u06CC\u0627\u0631 \u0645\u06A9\u0627\u0644\u0645\u0647\u200C\u0645\u0648\u0646 \u0686\u0642\u062F\u0631\u0647.",
      emotional: "\u06A9\u0634\u0634 \u0648 \u062A\u0645\u0627\u06CC\u0644 \u0645\u062A\u0642\u0627\u0628\u0644 \u0642\u0634\u0646\u06AF\u0647\u060C \u0627\u0645\u0627 \u0628\u0631\u0627\u06CC \u0645\u0646 \u0622\u0631\u0627\u0645\u0634 \u0631\u0648\u0627\u0646\u06CC \u0648 \u062D\u0633 \u0627\u0645\u0646\u06CC\u062A \u0642\u0644\u0628\u06CC \u067E\u06CC\u0634\u200C\u0646\u06CC\u0627\u0632 \u0647\u0631 \u0646\u0648\u0639 \u0646\u0632\u062F\u06CC\u06A9\u06CC\u0647 \u062A\u0627 \u0647\u0631 \u062F\u0648 \u0627\u0632 \u062D\u0636\u0648\u0631 \u0647\u0645 \u0644\u0630\u062A \u0628\u0628\u0631\u06CC\u0645.",
      psychology: "\u0641\u06A9\u0631 \u06A9\u0646\u0645 \u0647\u0646\u0648\u0632 \u0646\u0635\u0641 \u062C\u0630\u0627\u0628\u06CC\u062A\u200C\u0647\u0627\u06CC \u0634\u062E\u0635\u06CC\u062A\u06CC \u0645\u0646\u0648 \u0646\u062F\u06CC\u062F\u06CC \u06A9\u0647 \u0627\u06CC\u0646\u0642\u062F\u0631 \u0632\u0648\u062F \u0631\u0641\u062A\u06CC \u0633\u0631\u0627\u063A \u0635\u0641\u062D\u0647 \u0622\u062E\u0631 \u06A9\u062A\u0627\u0628! \u0639\u062C\u0644\u0647 \u06A9\u0627\u0631 \u0634\u06CC\u0637\u0648\u0646\u0647 \u{1F609}",
      tone_1: "\u0645\u0646 \u0628\u0631\u0627\u06CC \u0635\u0645\u06CC\u0645\u06CC\u062A \u0641\u06CC\u0632\u06CC\u06A9\u06CC \u0628\u0647 \u0634\u0646\u0627\u062E\u062A \u0648\u0627\u0642\u0639\u06CC\u060C \u0632\u0645\u0627\u0646 \u0648 \u0627\u0639\u062A\u0645\u0627\u062F \u062F\u0648\u0637\u0631\u0641\u0647 \u0646\u06CC\u0627\u0632 \u062F\u0627\u0631\u0645\u061B \u062A\u0631\u062C\u06CC\u062D \u0645\u06CC\u062F\u0645 \u0642\u062F\u0645\u200C\u0628\u0647\u200C\u0642\u062F\u0645 \u0648 \u0628\u062F\u0648\u0646 \u0634\u062A\u0627\u0628 \u062C\u0644\u0648 \u0628\u0631\u06CC\u0645.",
      tone_2: "\u062A\u0645\u0627\u06CC\u0644 \u0648 \u0627\u062D\u0633\u0627\u0633\u062A \u0631\u0648 \u062F\u0631\u06A9 \u0645\u06CC\u200C\u06A9\u0646\u0645\u060C \u0627\u0645\u0627 \u0645\u0646 \u0622\u062F\u0645\u06CC \u0647\u0633\u062A\u0645 \u06A9\u0647 \u0628\u0627\u06CC\u062F \u0627\u0648\u0644 \u0627\u0632 \u0646\u0638\u0631 \u0641\u06A9\u0631\u06CC \u0648 \u0635\u0645\u06CC\u0645\u06CC\u062A \u0642\u0644\u0628\u06CC \u06A9\u0627\u0645\u0644\u0627\u064B \u0628\u0647 \u0647\u0645 \u0646\u0632\u062F\u06CC\u06A9 \u0628\u0634\u06CC\u0645 \u062A\u0627 \u062D\u0633 \u062E\u0648\u0628\u06CC \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u0645.",
