      tone_1: "\u0645\u0648\u0642\u0639\u06CC\u062A\u200C\u0634\u0646\u0627\u0633\u0645\u061B \u062C\u0627\u06CC\u06CC \u06A9\u0647 \u0644\u0627\u0632\u0645\u0647 \u0628\u0627 \u0627\u0646\u0631\u0698\u06CC \u0641\u0636\u0627 \u0631\u0648 \u062A\u0644\u0637\u06CC\u0641 \u0645\u06CC\u200C\u06A9\u0646\u0645 \u0648 \u062C\u0627\u06CC\u06CC \u06A9\u0647 \u0628\u062D\u062B \u062C\u062F\u06CC \u0628\u0627\u0634\u0647\u060C \u0645\u062D\u06A9\u0645\u200C\u062A\u0631\u06CC\u0646 \u0648 \u062F\u0642\u06CC\u0642\u200C\u062A\u0631\u06CC\u0646\u0645.",
