      charismatic: "\u062F\u0633\u062A\u0648\u0631 \u0642\u0634\u0646\u06AF\u06CC \u0628\u0648\u062F! \u0648\u0644\u06CC \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u0627\u0648\u0644 \u0639\u06CC\u0627\u0631 \u0647\u0645\u0646\u0634\u06CC\u0646\u06CC \u0633\u0646\u062C\u06CC\u062F\u0647 \u0645\u06CC\u0634\u0647\u060C \u0628\u0639\u062F \u0633\u0648\u0631\u067E\u0631\u0627\u06CC\u0632\u0647\u0627\u06CC \u062E\u0648\u0634\u0645\u0632\u0647 \u0631\u0648\u0646\u0645\u0627\u06CC\u06CC \u0645\u06CC\u0634\u0646. \u0641\u06A9\u0631 \u0645\u06CC\u200C\u06A9\u0646\u06CC \u0628\u0631\u0646\u062F\u0647 \u0627\u06CC\u0646 \u0686\u0627\u0644\u0634 \u0628\u0634\u06CC\u061F \u2728",
