      tone_2: "\u0639\u0627\u0634\u0642 \u0627\u06CC\u0646 \u0645\u062F\u0644 \u0628\u0627\u062C\u200C\u06AF\u06CC\u0631\u06CC\u200C\u0647\u0627\u06CC \u0634\u06CC\u0631\u06CC\u0646\u062A\u0645! \u0628\u0627\u0634\u0647 \u0628\u0647 \u0634\u0631\u0637\u06CC \u06A9\u0647 \u067E\u0627\u0633\u062A\u06CC\u0644 \u062A\u0631\u0634\u200C\u0647\u0627 \u0633\u0647\u0645 \u0645\u0646 \u0628\u0627\u0634\u0647 \u0648 \u0634\u06A9\u0644\u0627\u062A\u200C\u0647\u0627 \u0633\u0647\u0645 \u062A\u0648 \u{1F604}",
