    bodyLanguage: "\u0644\u0628\u062E\u0646\u062F \u06A9\u0646\u0627\u06CC\u0647\u200C\u0622\u0645\u06CC\u0632 \u062C\u0630\u0627\u0628\u060C \u0627\u0628\u0631\u0648\u06CC \u0628\u0627\u0644\u0627 \u0627\u0646\u062F\u0627\u062E\u062A\u0647\u060C \u0631\u06CC\u0644\u06A9\u0633 \u0648 \u067E\u0631\u0627\u0646\u0631\u0698\u06CC.",
